mapper.select:
select id, tenant_id, username, display_name, mobile, email, password_hash,
       account_type, status, last_login_at
from auth_user
where tenant_id = #{tenantId}
  and username = #{username}
  and deleted = 0

select id, tenant_id, username, display_name, mobile, email, password_hash,
       account_type, status, last_login_at
from auth_user
where tenant_id = #{tenantId}
  and id = #{userId}
  and deleted = 0

mapper.update:
update auth_user
set last_login_at = now(), updated_at = now()
where tenant_id = #{tenantId}
  and id = #{userId}
